examples.template:
MonarchMiniMonth(
    selection: $day,
    visibleMonth: $month,
    today: {{today|date}},
    dayInfo: { date in
        if calendar.isDate(date, inSameDayAs: {{events.0.date|date}}) {
            return MonarchMiniMonthDayInfo(dots: [{{events.0.dots.0|tone}}], description: {{events.0.description}})
        }
        if calendar.isDate(date, inSameDayAs: {{events.1.date|date}}) {
            return MonarchMiniMonthDayInfo(dots: [{{events.1.dots.0|tone}}, {{events.1.dots.1|tone}}], description: {{events.1.description}})
        }
        if calendar.isDate(date, inSameDayAs: {{events.2.date|date}}) {
            return MonarchMiniMonthDayInfo(dots: [{{events.2.dots.0|tone}}], description: {{events.2.description}})
        }
        if calendar.isDate(date, inSameDayAs: {{events.3.date|date}}) {
            return MonarchMiniMonthDayInfo(dots: [{{events.3.dots.0|tone}}, {{events.3.dots.1|tone}}, {{events.3.dots.2|tone}}], description: {{events.3.description}})
        }
        return nil
    }
)
.environment(\.calendar, calendar)
.environment(\.locale, Locale(identifier: {{locale}}))

examples.setupTemplate:
@State private var day: Date? = {{value|date}}
@State private var month = {{value|date}}
private var calendar: Calendar {
    var calendar = Calendar(identifier: .gregorian)
    calendar.locale = Locale(identifier: {{locale}})
    calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
    return calendar
}

examples.setup:
@State private var day: Date? = Date(timeIntervalSince1970: 1_794_268_800)
@State private var month = Date(timeIntervalSince1970: 1_794_268_800)
private var calendar: Calendar {
    var calendar = Calendar(identifier: .gregorian)
    calendar.locale = Locale(identifier: "en-GB")
    calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
    return calendar
}

examples.code:
MonarchMiniMonth(
    selection: $day,
    visibleMonth: $month,
    today: Date(timeIntervalSince1970: 1_793_750_400),
    dayInfo: { date in
        if calendar.isDate(date, inSameDayAs: Date(timeIntervalSince1970: 1_793_836_800)) {
            return MonarchMiniMonthDayInfo(dots: [.accent], description: "1 event")
        }
        if calendar.isDate(date, inSameDayAs: Date(timeIntervalSince1970: 1_794_268_800)) {
            return MonarchMiniMonthDayInfo(dots: [.accent, .info], description: "2 events")
        }
        if calendar.isDate(date, inSameDayAs: Date(timeIntervalSince1970: 1_794_960_000)) {
            return MonarchMiniMonthDayInfo(dots: [.warning], description: "Deadline")
        }
        if calendar.isDate(date, inSameDayAs: Date(timeIntervalSince1970: 1_795_478_400)) {
            return MonarchMiniMonthDayInfo(dots: [.accent, .success, .danger], description: "3 events")
        }
        return nil
    }
)
.environment(\.calendar, calendar)
.environment(\.locale, Locale(identifier: "en-GB"))
